head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gViewerStat = "R"; // 처리시 뷰=P,  조회시 뷰=R
scwin.gWinTyp = '';
scwin.search_yn = false;
// 화면 리사이징

scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;
scwin.gSndlocTpCd;
scwin.gDate;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name getCode
 * @description get Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getCode = async function() {
    panel_2.hide();
    panel_4.hide(); // 공시구분은 시장운영팀만 보여준다.(2016.06.17)

    const strDepCd = js_dep_cd.substring(0, 2);
    // alert("strDepCd-->"+strDepCd);

    // 유가 공시팀(26**), 코스닥 공시팀(34**) => 보여준다.
    // if (js_dep_cd.substring(0,2) == '26'  || js_dep_cd.substring(0,2) == '34' ) {
    // if (js_dep_cd.substring(0,1) == '2'  || js_dep_cd.substring(0,2) == '34' ) {
    if (strDepCd === '24' || strDepCd === '25' || strDepCd === '2B') {
        // 24=채권상장, 25=상장심사부, 2B=증권상품
        panel_2.show("");
    } else if (strDepCd === '26' || strDepCd === '34') {
        // 공시팀인경우 당번만 보여준다 2013.03.26
        if (scwin.gDepCd === '2610' || scwin.gDepCd === '3410') {
            // 공시제도팀의 경우 팀장, 팀원 모두 공시제도팀공시만 볼 수 있다. 20210312 - IT운영팀
            panel_2.hide();
        } else {
            if (scwin.gJobTitle === '09' || scwin.gDutyYn === 'Y' || scwin.gDutyChrg === 'Y') {
                panel_2.show("");
            }
        }
    }

    // 2010.03.05 시장조치검증관련 추가
    if (strDepCd === '34') {
        panel_FNC_COND.show("");
    } else if (strDepCd === '26' || strDepCd === '3B') {
        // 유가 또는 코넥스 공시팀일 경우 '분기매출액해당여부', '분기매출액' 항목 표출
        panel_FNC_COND.hide();
        $c.cm.setColumnProp(grd_Grid, "FNC_COND", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "EMBZL", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "REDU_LOSS_RTO_EXCS50PCT_YN", "Show", false);
    } else {
        panel_FNC_COND.hide();
        $c.cm.setColumnProp(grd_Grid, "FNC_COND", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "EMBZL", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "QTR_SALES", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "QTR_SALES_YN", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "REDU_LOSS_RTO_EXCS50PCT_YN", "Show", false);
    }
    if (strDepCd === '22' || strDepCd === '32') {
        // 공시구분은 시장운영팀만 보여준다.(2016.06.17)
        panel_4.show("");
    }
    if (js_market === "1" || js_market === "2") {
        panel_MEMO.show("");
    } else {
        panel_MEMO.hide();
    }

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    // dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 익일전송대상  셋팅
    const sbmOptions3 = {
        id : "sbm_dts_NxtddTp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_NxtddTp=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    // gDate = getObjectValue(edt_SrchDay) ;
    // 현재날짜 셋팅
    edt_SrchDay.setValue($c.ut.cGetToday("yyyymmdd"));
    scwin.gDate = edt_SrchDay.getValue();
    if (scwin.gLdMktTp === '1') {
        panel_kos1.hide();
        panel_kos2.hide();
    } else {
        panel_kos1.show("");
        panel_kos2.show("");
    }
};

/**
 * @method
 * @name depListLoadComplete
 * @description dep List Load Complete 처리
 * @returns {void}
 * @hidden N
 */
scwin.depListLoadComplete = function() {
    cmb_TeamList.setValue(js_dep_cd);
    // 부서코드 가져온후에  초기검색
    scwin.initSearch();

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !공시처리현황--;
클릭-- > async function(pReload) {
    // 일자 체크
    if (edt_SrchDay.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_SrchDay.focus();
        return;
    }
    let vStatCnt = 0;
    if (chb_stat_00.checked === true) {
        vStatCnt++;
    }
    if (chb_stat_02.checked === true) {
        vStatCnt++;
    }
    if (chb_stat_10.checked === true) {
        vStatCnt++;
    }
    if (chb_stat_01.checked === true) {
        vStatCnt++;
    }
    if (chb_stat_3A.checked === true) {
        vStatCnt++;
    }
    if (chb_stat_3B.checked === true) {
        vStatCnt++;
    }
    if (chb_stat_15.checked === true) {
        vStatCnt++;
    }
    if (chb_stat_20.checked === true) {
        vStatCnt++;
    }
    if (chb_stat_40.checked === true) {
        vStatCnt++;
    }
    if (chb_reg.checked === true) {
        vStatCnt++;
    }

    // 처리상태 1개 이상 체크
    if (vStatCnt < 1) {
        await $c.win.alert("처리상태를 한개 이상  선택하시오.");
        chb_stat_00.focus();
        return;
    }
    scwin.gDate = edt_SrchDay.getValue();

    // 유가 공시팀(26**), 코스닥 공시팀(34**) =>  선택부서로
    // if (js_dep_cd.substring(0,2) == '26'  || js_dep_cd.substring(0,2) == '34' ) {
    if (js_dep_cd.substring(0, 1) === '2' || js_dep_cd.substring(0, 2) === '34') {
        scwin.gDepCd = cmb_TeamList.getValue();
        scwin.gEmpNo = cmb_EmpList.getValue();
    } else {
        scwin.gDepCd = ""; // 부서코드 없음 => 전체
        scwin.gEmpNo = "";
    }
    fn_Search(pReload);
};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "0";
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !공시처리현황--;
클릭-- > function(pReload) {
    $c.cm.ShowWin_yn(grd_Grid, scwin.search_yn);

    /******************************************************************
    	2009.09.01 채권공시관련 - 채권상장팀이면 시장구분을 '4'로 셋팅
     ******************************************************************/
    if (js_bond_yn === "Y") {
        scwin.gLdMktTp = "4";
    }
    txb_TotalCnt.setValue("총  건");
    const url_list = "/DisclosureStatus.do?method=listDisclosureStatus&inputMessageId=DSCLSTATUSCOND_IN" + "&outputMessageId=DSCLSTATUSLIST_OUT";
    const url_count = "/DisclosureStatus.do?method=countDisclosureStatus&inputMessageId=DSCLSTATUSCOND_IN" + "&outputMessageId=DSCLSTATUSCNT_OUT";
    const url_cond = "&ACPT_DATE=" + scwin.gDate + "&DEP_CD=" + scwin.gDepCd + "&EMP_NO=" + scwin.gEmpNo + "&LD_MKT_TP=" + scwin.gLdMktTp + "&STAT_00=" + scwin.getChkValue(chb_stat_00) + "&STAT_02=" + scwin.getChkValue(chb_stat_02) + "&STAT_01=" + scwin.getChkValue(chb_stat_01) + "&STAT_10=" + scwin.getChkValue(chb_stat_10) + "&STAT_20=" + scwin.getChkValue(chb_stat_20) + "&STAT_3A=" + scwin.getChkValue(chb_stat_3A) + "&STAT_3B=" + scwin.getChkValue(chb_stat_3B) + "&STAT_15=" + scwin.getChkValue(chb_stat_15) + "&STAT_40=" + scwin.getChkValue(chb_stat_40) + "&STAT_REG=" + scwin.getChkValue(chb_reg) + "&ISUR_NM_CD=" + txb_isur_cd.getValue() + "&NXTDD_TP=" + cmb_NxtddTp.getValue() + "&SECT_TP=" + cmb_SectTp.getValue() + "&UP_DEP_CD=" + js_belngdepcd + "&FNC_COND=" + scwin.getChkValue(chk_FNC_COND) + "&RSN_CLSS_CD=" + rdo_discls.getValue();

    // alert('[pReload]'+pReload);

    let url_log = '';
    if (pReload !== 'Y') {
        // 자동refresh일때는 로그 없앰
        url_log = "&SCREN_ID=" + 'ULDSTF10200.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    }

    // 그리드의 데이타 조회
    dts_DsclStatusList.DataID = encodeURI(url_list + url_cond + url_log);
    dts_DsclStatusList.reset();

    // 처리상태별 건수
    dts_DsclStatusCnt.DataID = encodeURI(url_count + url_cond);
    dts_DsclStatusCnt.reset();
    /*
    var fFrame = frame.Provider("/pageIndex").selPageID;
    var fname = frame.FrameID;
    if (fFrame == fname) {
        ShowWin(grd_Grid);
    }
     */

};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclStatusList.getCellData(Number(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_DsclStatusList.getCellData(Number(obj), "FORM_CD");
    // gFormVer = dts_DsclStatusList.NameString(eval(obj),"FORM_VER");
    scwin.gIsurCd = dts_DsclStatusList.getCellData(Number(obj), "ISUR_CD");
    // gSndlocTpCd = dts_DsclStatusList.NameString(eval(obj),"SNDLOC_TP_CD");
    // alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};

/**
 * @method
 * @name initSearch
 * @description 화면 로딩시 디폴트 검색
 * @returns {void}
 * @hidden N
 */
scwin.initSearch = function() {
    // fn_Search();
    scwin.reload('N');
};

/**
 * @method
 * @name reload
 * @description reload 처리
 * @param {*} pReload pReload
 * @returns {void}
 * @hidden N
 */
scwin.reload = function(pReload) {
    fn_CheckCond(pReload);
    setTimeout("fn_Reload('Y')", 30000); // 1초 = 1000 , 30초 = 30000

};

/**
 * @method
 * @name checkAll
 * @description 전체가 체크일때
 * @returns {void}
 * @hidden N
 */
scwin.checkAll = function() {
    // 전체가 체크일때
    if (chb_stat_all.checked === true) {
        chb_stat_00.setValue(1);
        chb_stat_02.setValue(1);
        chb_stat_01.setValue(1);
        chb_stat_10.setValue(1);
        chb_stat_20.setValue(1);
        chb_stat_3A.setValue(1);
        chb_stat_3B.setValue(1);
        chb_stat_15.setValue(1);
        chb_stat_40.setValue(1);
        chb_reg.setValue(1);
    } else {
        chb_stat_00.setValue(0);
        chb_stat_02.setValue(0);
        chb_stat_01.setValue(0);
        chb_stat_10.setValue(0);
        chb_stat_20.setValue(0);
        chb_stat_3A.setValue(0);
        chb_stat_3B.setValue(0);
        chb_stat_15.setValue(0);
        chb_stat_40.setValue(0);
        chb_reg.setValue(0);
    }
};

/**
 * @method
 * @name popupFncInfo
 * @description popup Fnc Info 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popupFncInfo = async function() {
    let url = "/dsclproc/ULDSTF10201.gfm?" + "gAcptNo=" + scwin.gAcptNo + "&gMainFormCd=" + scwin.gMainFormCd + "&gWinTyp=" + scwin.gWinTyp + "&frameID=" + frame.FrameID;
    let winTitle = "실질심사 상세";
    if ($c.frame.path("/top") !== undefined) {
        $c.frame.path("/top").WinOpen("ULDSTF10201" + scwin.gAcptNo, url, winTitle, 1000, 745 + 30);
    } else {
        await $c.frame.CreateFrame("ULDSTF10201" + scwin.gAcptNo, "/dsclproc/ULDSTF10201.gfm", winTitle, 200, 5, 875, 745 + 30, "window", 0, 0, true);
    }
};

/**
 * @method
 * @name popupSaleInfo
 * @description popup Sale Info 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popupSaleInfo = async function() {
    let url = "/dsclproc/ULDSTF10202.gfm?" + "gAcptNo=" + scwin.gAcptNo + "&gMainFormCd=" + scwin.gMainFormCd + "&gWinTyp=" + scwin.gWinTyp + "&frameID=" + frame.FrameID;
    let winTitle = "분기매출액 상세";
    if ($c.frame.path("/top") !== undefined) {
        $c.frame.path("/top").WinOpen("ULDSTF10202" + scwin.gAcptNo, url, winTitle, 875, 440 + 30);
    } else {
        await $c.frame.CreateFrame("ULDSTF10201" + scwin.gAcptNo, "/dsclproc/ULDSTF10202.gfm", winTitle, 200, 5, 875, 440 + 30, "window", 0, 0, true);
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.setContnId(row);
    if (colid === "DOC_TITLE") {
        $c.stf.fn_OpenNoDisclViewer(scwin.gAcptNo, scwin.gViewerStat, js_emp_no, js_dep_cd, js_jobtitl, js_duty, js_duty_chrg, 'S', dts_DutyStatus); // 2013.05.14
        // fn_OpenNoDisclViewer(gAcptNo, gViewerStat);

    } else if (colid === "ACPT_DDTM") {
        $c.stf.openDisclAllList();
    } else if (colid === "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    } else if (colid === "FNC_COND" && dts_DsclStatusList.getCellData(row, "FNC_COND") !== '') {
        scwin.gWinTyp = '1';
        await scwin.popupFncInfo();
    } else if (colid === "EMBZL" && dts_DsclStatusList.getCellData(row, "EMBZL") !== '') {
        scwin.gWinTyp = '2';
        await scwin.popupFncInfo();
    } else if (colid === "REDU_LOSS_RTO_EXCS50PCT_YN" && dts_DsclStatusList.getCellData(row, "REDU_LOSS_RTO_EXCS50PCT_YN") !== '') {
        scwin.gWinTyp = '2';
        await scwin.popupFncInfo();
    } else if (colid === "QTR_SALES_YN" && dts_DsclStatusList.getCellData(row, "QTR_SALES_YN") !== '' && dts_DsclStatusList.getCellData(row, "QTR_SALES_YN") !== '미추출') {
        await scwin.popupSaleInfo();
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
