    // fn_InitSearch(); // 부서코드 가져온후에  초기검색되도록 변경 (2013.04.05)

    /******************************************************************
    	2009.09.01 채권공시관련 - 채권상장팀이면 문서구분을 보여주지 않음
     ******************************************************************/
    if (js_bond_yn === "Y") {
        cmb_SectTp.style.display = "none";
        label_5.style.display = "none";
    }
